#include <ranges>
#include <vector>

int main() {
  auto r = std::views::iota(0) | std::views::take(5);
  std::vector<int> a(r.begin(), r.end());                   // 1
  auto c = r | std::views::common;
  std::vector<int> b(c.begin(), c.end());                   // 2
  auto d = std::ranges::to<std::vector>(r);                 // 3
}

